package com.smirnovlabs.pohteleports.store;

import com.google.gson.Gson;
import com.smirnovlabs.pohteleports.model.Destination;
import com.smirnovlabs.pohteleports.model.TeleportEvent;
import org.junit.Test;
import static org.junit.Assert.assertEquals;

public class TeleportSavingsStoreTest
{
	@Test
	public void recordIncrementsCount()
	{
		TeleportSavingsStore s = new TeleportSavingsStore(new Gson());
		s.record(new TeleportEvent(Destination.NEXUS_VARROCK, 1));
		s.record(new TeleportEvent(Destination.NEXUS_VARROCK, 2));
		assertEquals(2, s.count(Destination.NEXUS_VARROCK));
		assertEquals(0, s.count(Destination.NEXUS_CAMELOT));
		assertEquals(2, s.totalCount());
	}

	@Test
	public void jsonRoundTrips()
	{
		TeleportSavingsStore a = new TeleportSavingsStore(new Gson());
		a.record(new TeleportEvent(Destination.MGLORY_EDGEVILLE, 5));
		String json = a.toJson();

		TeleportSavingsStore b = new TeleportSavingsStore(new Gson());
		b.loadJson(json);
		assertEquals(1, b.count(Destination.MGLORY_EDGEVILLE));
	}

	@Test
	public void loadJsonNullOrEmptyIsEmpty()
	{
		TeleportSavingsStore s = new TeleportSavingsStore(new Gson());
		s.loadJson(null);
		assertEquals(0, s.totalCount());
		s.loadJson("");
		assertEquals(0, s.totalCount());
	}

	@Test
	public void loadJsonSkipsUnknownIds()
	{
		TeleportSavingsStore s = new TeleportSavingsStore(new Gson());
		s.loadJson("{\"bogus:removed:destination\":7}");
		assertEquals(0, s.totalCount());
	}
}

package com.smirnovlabs.pohteleports.cost;

import com.smirnovlabs.pohteleports.model.Destination;
import org.junit.Test;
import static org.junit.Assert.assertEquals;

public class SavingsValuatorTest
{
	@Test
	public void gpTotalIsPerUseTimesCount()
	{
		SavingsValuator v = new SavingsValuator(id -> 60); // every rune = 60
		long per = v.gpPerUse(Destination.NEXUS_CAMELOT);  // 5 air + 1 law = 6 * 60
		assertEquals(360, per);
		assertEquals(3600, v.gpTotal(Destination.NEXUS_CAMELOT, 10));
	}

	@Test
	public void itemFractionUsesPriceOverCharges()
	{
		SavingsValuator v = new SavingsValuator(id -> 6000); // glory(6) = 6000
		assertEquals(1000, v.gpPerUse(Destination.MGLORY_EDGEVILLE)); // 6000 / 6
	}

	@Test
	public void noneValuesToZero()
	{
		assertEquals(0, new SavingsValuator(id -> 999).gpPerUse(Destination.NEXUS_UNKNOWN));
	}
}

package com.smirnovlabs.pohteleports.cost;

import java.util.Map;
import java.util.function.IntUnaryOperator;
import org.junit.Test;
import static org.junit.Assert.assertEquals;

public class CostBasisTest
{
	// price: itemId -> gp
	private final IntUnaryOperator price = id ->
	{
		switch (id)
		{
			case 1: return 5;
			case 2: return 300;
			case 3: return 100;
			default: return 0;
		}
	};

	@Test
	public void runesSumsPriceTimesQty()
	{
		assertEquals(5 * 3 + 300 * 1, CostBasis.runes(Map.of(1, 3, 2, 1)).gpPerUse(price));
	}

	@Test
	public void itemFractionDividesByCharges()
	{
		assertEquals(300 / 6, CostBasis.itemFraction(2, 6).gpPerUse(price)); // 50
	}

	@Test
	public void consumableMultipliesQty()
	{
		assertEquals(100 * 2, CostBasis.consumable(3, 2).gpPerUse(price));
	}

	@Test
	public void noneIsZero()
	{
		assertEquals(0, CostBasis.NONE.gpPerUse(price));
	}

	@Test
	public void craftedFractionAddsMakeRunesThenDividesByCharges()
	{
		// (base 300 + 5*fire@5 + 1*cosmic@100) / 5 = (300 + 25 + 100) / 5 = 85
		assertEquals(85, CostBasis.craftedFraction(2, Map.of(1, 5, 3, 1), 5).gpPerUse(price));
	}

	@Test
	public void craftedFractionZeroChargesIsZero()
	{
		assertEquals(0, CostBasis.craftedFraction(2, Map.of(1, 5), 0).gpPerUse(price));
	}

}

package com.smirnovlabs.pohteleports.detect;

import com.smirnovlabs.pohteleports.model.Destination;
import com.smirnovlabs.pohteleports.model.Transport;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/** Pins the struct-id -> Destination bridge and guarantees it covers every nexus destination. */
public class NexusStructIndexTest
{
	@Test
	public void resolvesKnownStructs()
	{
		assertEquals(Destination.NEXUS_VARROCK, NexusStructIndex.forStruct(450));
		assertEquals(Destination.NEXUS_GRAND_EXCHANGE, NexusStructIndex.forStruct(451));
		assertEquals(Destination.NEXUS_KHARYRLL, NexusStructIndex.forStruct(461));
		assertEquals(Destination.NEXUS_CIVITAS, NexusStructIndex.forStruct(855));
		assertEquals(Destination.NEXUS_TROLL_STRONGHOLD, NexusStructIndex.forStruct(467));
	}

	@Test
	public void bothMooringStructsMapToOneDestination()
	{
		assertEquals(Destination.NEXUS_MOORING_POINT, NexusStructIndex.forStruct(1187));
		assertEquals(Destination.NEXUS_MOORING_POINT, NexusStructIndex.forStruct(6423));
	}

	@Test
	public void unknownStructIsNull()
	{
		assertNull(NexusStructIndex.forStruct(-1));
		assertNull(NexusStructIndex.forStruct(99999));
	}

	@Test
	public void everyNexusDestinationIsBridged()
	{
		for (Destination d : Destination.values())
		{
			if (d.getTransport() == Transport.NEXUS && !d.getId().endsWith(":unknown"))
			{
				assertTrue("no struct maps to " + d, NexusStructIndex.mappedDestinations().contains(d));
			}
		}
	}

	@Test
	public void unknownBucketIsNotBridged()
	{
		// The catalog resolves real destinations; the Unknown bucket is a fallback, never a struct target.
		assertTrue(!NexusStructIndex.mappedDestinations().contains(Destination.NEXUS_UNKNOWN));
	}
}

package com.smirnovlabs.pohteleports.detect;

import com.smirnovlabs.pohteleports.model.Destination;
import com.smirnovlabs.pohteleports.model.TeleportEvent;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class DetectionRouterTest
{
	private static final int[] POH = {1984, 7040, 0};       // inside a POH instance
	private static final int[] VARROCK = {3212, 3424, 0};   // far away — a teleport

	private static class FakeState implements GameStateView
	{
		int tick = 0;
		boolean inPoh = true;
		int[] pos = POH;

		public int getVarbit(int id)
		{
			return 0;
		}

		public boolean isInPoh()
		{
			return inPoh;
		}

		public int currentTick()
		{
			return tick;
		}

		public int[] playerPos()
		{
			return pos;
		}
	}

	private static final TeleportRecognizer ALWAYS = (e, s) -> Optional.of(Destination.NEXUS_VARROCK);

	private MenuInteraction click()
	{
		return new MenuInteraction("Teleport", "Varrock", 0);
	}

	@Test
	public void countsOnCoordJumpAfterArming()
	{
		FakeState st = new FakeState();
		List<TeleportEvent> out = new ArrayList<>();
		DetectionRouter r = new DetectionRouter(List.of(ALWAYS), st, out::add);
		r.onGameTick();               // establish lastPos = POH
		r.onMenuInteraction(click()); // arm — no count yet
		assertEquals(0, out.size());
		st.tick = 1;
		st.pos = VARROCK;             // teleported
		r.onGameTick();               // jump -> count
		assertEquals(1, out.size());
		assertEquals(Destination.NEXUS_VARROCK, out.get(0).getDestination());
	}

	@Test
	public void doesNotCountUntilTheJump()
	{
		FakeState st = new FakeState();
		List<TeleportEvent> out = new ArrayList<>();
		DetectionRouter r = new DetectionRouter(List.of(ALWAYS), st, out::add);
		r.onGameTick();
		r.onMenuInteraction(click());
		st.tick = 1;
		r.onGameTick();               // still in POH, no jump
		assertEquals(0, out.size());
	}

	@Test
	public void walkingNeverCounts()
	{
		FakeState st = new FakeState();
		List<TeleportEvent> out = new ArrayList<>();
		DetectionRouter r = new DetectionRouter(List.of(ALWAYS), st, out::add);
		r.onGameTick();
		r.onMenuInteraction(click());
		for (int t = 1; t <= 5; t++)
		{
			st.tick = t;
			st.pos = new int[]{POH[0] + 2 * t, POH[1], 0}; // 2 tiles/tick — running
			r.onGameTick();
		}
		assertEquals(0, out.size());
	}

	@Test
	public void wildernessWarningDelayStillCounts()
	{
		FakeState st = new FakeState();
		List<TeleportEvent> out = new ArrayList<>();
		DetectionRouter r = new DetectionRouter(List.of(ALWAYS), st, out::add);
		r.onGameTick();
		r.onMenuInteraction(click()); // armed at tick 0
		st.tick = 1;
		r.onGameTick();               // warning showing, no jump
		st.tick = 2;
		r.onGameTick();               // clicking "Enter Wilderness", no jump
		st.tick = 3;
		st.pos = VARROCK;             // now it fires
		r.onGameTick();
		assertEquals(1, out.size());
	}

	@Test
	public void discardsAfterWindowThenAJumpDoesNotCount()
	{
		FakeState st = new FakeState();
		List<TeleportEvent> out = new ArrayList<>();
		DetectionRouter r = new DetectionRouter(List.of(ALWAYS), st, out::add);
		r.onGameTick();
		r.onMenuInteraction(click()); // armed at tick 0
		for (int t = 1; t <= 10; t++) // 10 ticks with no jump -> expires
		{
			st.tick = t;
			r.onGameTick();
		}
		st.tick = 11;
		st.pos = VARROCK;             // a jump, but the arm is long gone
		r.onGameTick();
		assertEquals(0, out.size());
	}

	@Test
	public void ignoresInteractionsOutsidePoh()
	{
		FakeState st = new FakeState();
		st.inPoh = false;
		List<TeleportEvent> out = new ArrayList<>();
		DetectionRouter r = new DetectionRouter(List.of(ALWAYS), st, out::add);
		r.onGameTick();
		r.onMenuInteraction(click()); // not armed
		st.tick = 1;
		st.pos = VARROCK;
		r.onGameTick();
		assertEquals(0, out.size());
	}

	@Test
	public void firstMatchingRecognizerWins()
	{
		FakeState st = new FakeState();
		List<TeleportEvent> out = new ArrayList<>();
		TeleportRecognizer none = (e, s) -> Optional.empty();
		DetectionRouter r = new DetectionRouter(List.of(none, ALWAYS), st, out::add);
		r.onGameTick();
		r.onMenuInteraction(click());
		st.tick = 1;
		st.pos = VARROCK;
		r.onGameTick();
		assertEquals(1, out.size());
		assertEquals(Destination.NEXUS_VARROCK, out.get(0).getDestination());
	}

	@Test
	public void traceReportsArmAndCount()
	{
		FakeState st = new FakeState();
		List<TeleportEvent> out = new ArrayList<>();
		List<String> traces = new ArrayList<>();
		DetectionRouter r = new DetectionRouter(List.of(ALWAYS), st, out::add, traces::add);
		r.onGameTick();
		r.onMenuInteraction(click());
		st.tick = 1;
		st.pos = VARROCK;
		r.onGameTick();
		assertTrue("expected an 'armed' trace", traces.stream().anyMatch(t -> t.startsWith("armed")));
		assertTrue("expected a 'counted' trace", traces.stream().anyMatch(t -> t.startsWith("counted")));
	}

	@Test
	public void traceReportsNoMatch()
	{
		FakeState st = new FakeState();
		List<TeleportEvent> out = new ArrayList<>();
		List<String> traces = new ArrayList<>();
		TeleportRecognizer none = (e, s) -> Optional.empty();
		DetectionRouter r = new DetectionRouter(List.of(none), st, out::add, traces::add);
		r.onMenuInteraction(click());
		assertTrue("expected a 'no match' trace", traces.stream().anyMatch(t -> t.startsWith("no match")));
	}
}

package com.smirnovlabs.pohteleports.detect;

import com.smirnovlabs.pohteleports.model.Destination;
import com.smirnovlabs.pohteleports.model.Transport;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;
import org.junit.Test;
import static org.junit.Assert.assertEquals;

public class NexusRecognizerTest
{
	private static final int NEXUS_OBJ = 100;

	private final Map<String, Destination> nameMap = Map.of(
		"varrock", Destination.NEXUS_VARROCK,
		"camelot", Destination.NEXUS_CAMELOT);

	private static class St implements GameStateView
	{
		int v = 0;

		public int getVarbit(int id)
		{
			return v;
		}

		public boolean isInPoh()
		{
			return true;
		}

		public int currentTick()
		{
			return 0;
		}

		public int[] playerPos()
		{
			return null;
		}
	}

	private NexusRecognizer rec()
	{
		return new NexusRecognizer(NEXUS_OBJ, nameMap);
	}

	@Test
	public void listPickResolvesByName()
	{
		assertEquals(Optional.of(Destination.NEXUS_VARROCK),
			rec().onMenuInteraction(new MenuInteraction("Teleport", "Varrock", 0), new St()));
	}

	@Test
	public void openingMenuIsNotCounted()
	{
		assertEquals(Optional.empty(),
			rec().onMenuInteraction(new MenuInteraction("Teleport Menu", "Portal Nexus", NEXUS_OBJ), new St()));
	}

	@Test
	public void configureIsNotCounted()
	{
		assertEquals(Optional.empty(),
			rec().onMenuInteraction(new MenuInteraction("Configure", "Portal Nexus", NEXUS_OBJ), new St()));
	}

	@Test
	public void foreignTeleportIsIgnored()
	{
		// a jewellery-box "Teleport -> Ferox Enclave" (not on the nexus object, not a nexus name)
		assertEquals(Optional.empty(),
			rec().onMenuInteraction(new MenuInteraction("Teleport", "Ferox Enclave", 555), new St()));
	}

	@Test
	public void genericDefaultWithoutCatalogFallsToUnknown()
	{
		// A bare left-click "Teleport" on the nexus object, no catalog to resolve it -> Unknown.
		assertEquals(Optional.of(Destination.NEXUS_UNKNOWN),
			rec().onMenuInteraction(new MenuInteraction("Teleport", "", NEXUS_OBJ), new St()));
	}

	@Test
	public void listPickStripsKeyboardShortcutPrefix()
	{
		// Real nexus interface pick: option='Teleport' target='[4] Civitas illa Fortis'
		NexusRecognizer r = new NexusRecognizer(NEXUS_OBJ, Map.of("civitas illa fortis", Destination.NEXUS_CIVITAS));
		assertEquals(Optional.of(Destination.NEXUS_CIVITAS),
			r.onMenuInteraction(new MenuInteraction("Teleport", "[4] Civitas illa Fortis", 1), new St()));
	}

	/** Build the nexus name map exactly like the plugin's byName(NEXUS) does. */
	private static Map<String, Destination> realNexusNameMap()
	{
		Map<String, Destination> m = new HashMap<>();
		for (Destination d : Destination.values())
		{
			if (d.getTransport() == Transport.NEXUS && !d.getId().endsWith(":unknown"))
			{
				m.put(d.getDisplayName().toLowerCase(Locale.ROOT), d);
			}
		}
		return m;
	}

	@Test
	public void realNameMapMatchesCapturedMenuPicks()
	{
		NexusRecognizer r = new NexusRecognizer(NEXUS_OBJ, realNexusNameMap());
		St st = new St();
		assertEquals("West Ardougne map-pick", Optional.of(Destination.NEXUS_WEST_ARDOUGNE),
			r.onMenuInteraction(new MenuInteraction("Teleport", "[K] West Ardougne", 1), st));
		assertEquals("Civitas list-pick", Optional.of(Destination.NEXUS_CIVITAS),
			r.onMenuInteraction(new MenuInteraction("Teleport", "[4] Civitas illa Fortis", 1), st));
		assertEquals("Grand Exchange direct object click", Optional.of(Destination.NEXUS_GRAND_EXCHANGE),
			r.onMenuInteraction(new MenuInteraction("Grand Exchange", "Portal Nexus", NEXUS_OBJ), st));
	}

	@Test
	public void nonBreakingSpaceSeparatorStillMatches()
	{
		// Live nexus picks separate the "[K]" shortcut from the name with a non-breaking
		// space (U+00A0), not a normal space — stripKey must fold it (the 2026-08-16 bug).
		NexusRecognizer r = new NexusRecognizer(NEXUS_OBJ, realNexusNameMap());
		assertEquals(Optional.of(Destination.NEXUS_WEST_ARDOUGNE),
			r.onMenuInteraction(new MenuInteraction("Teleport", "[K] West Ardougne", 1), new St()));
		assertEquals(Optional.of(Destination.NEXUS_DAREEYAK),
			r.onMenuInteraction(new MenuInteraction("Teleport", "[R] Dareeyak (Crazy Archaeologist)", 1), new St()));
	}

	@Test
	public void objectDirectOptionNamesDestination()
	{
		// Real nexus object option: option='Grand Exchange' target='Portal Nexus'
		NexusRecognizer r = new NexusRecognizer(NEXUS_OBJ, Map.of("grand exchange", Destination.NEXUS_GRAND_EXCHANGE));
		assertEquals(Optional.of(Destination.NEXUS_GRAND_EXCHANGE),
			r.onMenuInteraction(new MenuInteraction("Grand Exchange", "Portal Nexus", NEXUS_OBJ), new St()));
	}

	// ---- Cache-catalog rescue + left-click-default layer (only fires when the catalog is loaded) ----

	@Test
	public void catalogRescuesUnrecognizedNameViaCache()
	{
		// Name we deliberately do NOT have in the name map, but the cache does (struct 6417 = "Dareeyak").
		NexusRecognizer r = new NexusRecognizer(NEXUS_OBJ, nameMap, loadedCatalog());
		assertEquals(Optional.of(Destination.NEXUS_DAREEYAK),
			r.onMenuInteraction(new MenuInteraction("Teleport", "[F] Dareeyak", 0), new St()));
	}

	@Test
	public void catalogResolvesLeftClickDefaultViaVarbit()
	{
		// Left-click "Teleport" on the object; varbit 6653 encodes dest 21 -> struct 461 = Kharyrll.
		St st = new St();
		st.v = 21;
		NexusRecognizer r = new NexusRecognizer(NEXUS_OBJ, nameMap, loadedCatalog());
		assertEquals(Optional.of(Destination.NEXUS_KHARYRLL),
			r.onMenuInteraction(new MenuInteraction("Teleport", "", NEXUS_OBJ), st));
	}

	@Test
	public void unloadedCatalogFallsToUnknown()
	{
		// Catalog present but never loaded (empty cache) -> generic default falls to the Unknown bucket.
		NexusCatalog cold = new NexusCatalog();
		cold.ensureLoaded(new EmptyCache());
		NexusRecognizer r = new NexusRecognizer(NEXUS_OBJ, nameMap, cold);
		assertEquals(Optional.of(Destination.NEXUS_UNKNOWN),
			r.onMenuInteraction(new MenuInteraction("Teleport", "", NEXUS_OBJ), new St()));
	}

	@Test
	public void catalogDoesNotRescueForeignTeleports()
	{
		// A jewellery-box "Ferox Enclave" (not a nexus cache name, not on the nexus object) stays unclaimed.
		NexusRecognizer r = new NexusRecognizer(NEXUS_OBJ, nameMap, loadedCatalog());
		assertEquals(Optional.empty(),
			r.onMenuInteraction(new MenuInteraction("Teleport", "Ferox Enclave", 555), new St()));
	}

	private static NexusCatalog loadedCatalog()
	{
		NexusCatalog c = new NexusCatalog();
		c.ensureLoaded(new RecCache());
		return c;
	}

	/** Minimal cache: two destinations (Dareeyak / Kharyrll) with names, no primary/alt. */
	private static final class RecCache implements CacheView
	{
		private final Map<Integer, Integer> dest = Map.of(20, 6417, 21, 461);
		private final Map<Integer, String> names = Map.of(6417, "Dareeyak", 461, "Kharyrll");

		public int[] enumKeys(int id)
		{
			return id == PohGameIds.NEXUS_DEST_ENUM ? new int[]{20, 21} : new int[0];
		}

		public int enumValue(int id, int key)
		{
			return id == PohGameIds.NEXUS_DEST_ENUM ? dest.getOrDefault(key, 0) : 0;
		}

		public int structInt(int structId, int paramId)
		{
			return 0;
		}

		public String structString(int structId, int paramId)
		{
			return paramId == PohGameIds.STRUCT_PARAM_NAME ? names.get(structId) : null;
		}
	}

	/** A cache that never becomes ready (enum absent). */
	private static final class EmptyCache implements CacheView
	{
		public int[] enumKeys(int id)
		{
			return new int[0];
		}

		public int enumValue(int id, int key)
		{
			return 0;
		}

		public int structInt(int structId, int paramId)
		{
			return 0;
		}

		public String structString(int structId, int paramId)
		{
			return null;
		}
	}
}

package com.smirnovlabs.pohteleports.detect;

import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/** Exercises the cache-folding logic (alt-&gt;primary, scry offset, name lookups) with a map-backed fake. */
public class NexusCatalogTest
{
	/** Map-backed {@link CacheView}: one enum (1377) plus per-struct int/string params. */
	private static final class FakeCache implements CacheView
	{
		final Map<Integer, Integer> dest = new LinkedHashMap<>();          // destId -> ownStruct
		final Map<Integer, Map<Integer, Integer>> ints = new HashMap<>();  // struct -> (param -> int)
		final Map<Integer, Map<Integer, String>> strs = new HashMap<>();   // struct -> (param -> string)

		FakeCache put(int destId, int struct, String name, int primary)
		{
			dest.put(destId, struct);
			if (name != null)
			{
				strs.computeIfAbsent(struct, k -> new HashMap<>()).put(PohGameIds.STRUCT_PARAM_NAME, name);
			}
			if (primary > 0)
			{
				ints.computeIfAbsent(struct, k -> new HashMap<>()).put(PohGameIds.STRUCT_PARAM_PRIMARY_STRUCT, primary);
			}
			return this;
		}

		@Override
		public int[] enumKeys(int enumId)
		{
			return enumId == PohGameIds.NEXUS_DEST_ENUM ? dest.keySet().stream().mapToInt(Integer::intValue).toArray() : new int[0];
		}

		@Override
		public int enumValue(int enumId, int key)
		{
			return enumId == PohGameIds.NEXUS_DEST_ENUM ? dest.getOrDefault(key, 0) : 0;
		}

		@Override
		public int structInt(int structId, int paramId)
		{
			return ints.getOrDefault(structId, Map.of()).getOrDefault(paramId, 0);
		}

		@Override
		public String structString(int structId, int paramId)
		{
			return strs.getOrDefault(structId, Map.of()).get(paramId);
		}
	}

	private NexusCatalog loaded()
	{
		FakeCache c = new FakeCache()
			.put(10, 450, "Varrock", 0)       // primary
			.put(11, 451, null, 450)          // Grand Exchange: alt of Varrock (name comes from primary)
			.put(12, 461, "Kharyrll", 0);     // primary
		NexusCatalog cat = new NexusCatalog();
		cat.ensureLoaded(c);
		return cat;
	}

	@Test
	public void loadsWhenCacheReady()
	{
		assertTrue(loaded().isLoaded());
	}

	@Test
	public void emptyCacheStaysUnloadedAndSafe()
	{
		NexusCatalog cat = new NexusCatalog();
		cat.ensureLoaded(new FakeCache()); // no dests => enumKeys empty
		assertFalse(cat.isLoaded());
		assertNull(cat.structForDestValue(10));
		assertNull(cat.structForName("varrock"));
	}

	@Test
	public void namesComeFromTheStruct()
	{
		assertEquals("Varrock", loaded().name(450));
		assertEquals("Kharyrll", loaded().name(461));
	}

	@Test
	public void sizeCountsDistinctNames()
	{
		// 450 (Varrock) + 461 (Kharyrll); 451 is an alt of 450 with no own name.
		assertEquals(2, loaded().size());
	}

	@Test
	public void altDestFoldsToPrimaryStruct()
	{
		assertEquals(Integer.valueOf(450), loaded().structForDestValue(10));
		assertEquals(Integer.valueOf(450), loaded().structForDestValue(11)); // GE alt -> Varrock primary
		assertEquals(Integer.valueOf(461), loaded().structForDestValue(12));
	}

	@Test
	public void scryVariantResolvesToSameDestination()
	{
		assertEquals(Integer.valueOf(450), loaded().structForDestValue(10 + 150));
		assertEquals(Integer.valueOf(461), loaded().structForDestValue(12 + 150));
	}

	@Test
	public void nameLookupIsCaseInsensitive()
	{
		assertEquals(Integer.valueOf(450), loaded().structForName("VARROCK"));
		assertEquals(Integer.valueOf(461), loaded().structForName("kharyrll"));
		assertNull(loaded().structForName("nowhere"));
	}

	// ---- Crash-safety: a cache read that throws (e.g. a wrong-typed param, the 2026-08-15
	// ---- getIntValue-on-string-param crash) must never propagate into the click handler. ----

	@Test
	public void survivesAThrowingStructReadAndStillLoadsOtherNames()
	{
		CacheView oneBad = new CacheView()
		{
			public int[] enumKeys(int id)
			{
				return id == PohGameIds.NEXUS_DEST_ENUM ? new int[]{10, 11} : new int[0];
			}

			public int enumValue(int id, int key)
			{
				return key == 10 ? 450 : 461;
			}

			public int structInt(int structId, int paramId)
			{
				if (structId == 450)
				{
					throw new IllegalArgumentException("trying to get int from string param");
				}
				return 0;
			}

			public String structString(int structId, int paramId)
			{
				return paramId == PohGameIds.STRUCT_PARAM_NAME && structId == 461 ? "Kharyrll" : null;
			}
		};

		NexusCatalog cat = new NexusCatalog();
		cat.ensureLoaded(oneBad); // must NOT throw
		assertTrue(cat.isLoaded());
		assertEquals("Kharyrll", cat.name(461));  // good destination loaded
		assertNull(cat.structForName("varrock")); // throwing destination skipped
	}

	@Test
	public void neverPropagatesWhenEveryStructReadThrows()
	{
		CacheView allThrow = new CacheView()
		{
			public int[] enumKeys(int id)
			{
				return id == PohGameIds.NEXUS_DEST_ENUM ? new int[]{10, 11} : new int[0];
			}

			public int enumValue(int id, int key)
			{
				return 450;
			}

			public int structInt(int structId, int paramId)
			{
				throw new IllegalArgumentException("boom");
			}

			public String structString(int structId, int paramId)
			{
				throw new IllegalStateException("boom");
			}
		};

		NexusCatalog cat = new NexusCatalog();
		cat.ensureLoaded(allThrow); // must NOT throw
		assertFalse(cat.isLoaded()); // nothing loaded, but the client handler is safe
	}
}

