package com.smirnovlabs.pohteleports.store;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.smirnovlabs.pohteleports.model.Destination;
import com.smirnovlabs.pohteleports.model.TeleportEvent;
import java.lang.reflect.Type;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;
import net.runelite.client.config.ConfigManager;

/**
 * Source of truth for per-destination use counts. Persists ONLY the counts
 * (GP is derived live from a static basis), keyed by stable
 * {@link Destination#getId()} strings so renames never crash a load.
 *
 * <p>Serialization is a pure method ({@link #toJson()} / {@link #loadJson})
 * so it is unit-testable without {@code ConfigManager}; the two
 * {@code ConfigManager} wrappers are thin one-liners.
 */
public class TeleportSavingsStore
{
	public static final String GROUP = "pohteleports";
	public static final String KEY_COUNTS = "counts";

	private static final Type MAP_TYPE = new TypeToken<Map<String, Integer>>()
	{
	}.getType();

	// The Plugin Hub forbids constructing fresh Gson instances; this is the client's injected Gson.
	private final Gson gson;
	private final EnumMap<Destination, Integer> counts = new EnumMap<>(Destination.class);

	public TeleportSavingsStore(Gson gson)
	{
		this.gson = gson;
	}

	public void record(TeleportEvent e)
	{
		counts.merge(e.getDestination(), 1, Integer::sum);
	}

	public int count(Destination d)
	{
		return counts.getOrDefault(d, 0);
	}

	public int totalCount()
	{
		int total = 0;
		for (int v : counts.values())
		{
			total += v;
		}
		return total;
	}

	public Map<Destination, Integer> snapshot()
	{
		return Collections.unmodifiableMap(new EnumMap<>(counts));
	}

	// --- pure serialization (testable without ConfigManager) ---

	String toJson()
	{
		Map<String, Integer> byId = new HashMap<>();
		for (Map.Entry<Destination, Integer> e : counts.entrySet())
		{
			byId.put(e.getKey().getId(), e.getValue());
		}
		return gson.toJson(byId, MAP_TYPE);
	}

	void loadJson(String json)
	{
		counts.clear();
		if (json == null || json.isEmpty())
		{
			return;
		}
		Map<String, Integer> byId = gson.fromJson(json, MAP_TYPE);
		if (byId == null)
		{
			return;
		}
		Map<String, Destination> index = new HashMap<>();
		for (Destination d : Destination.values())
		{
			index.put(d.getId(), d);
		}
		for (Map.Entry<String, Integer> e : byId.entrySet())
		{
			Destination d = index.get(e.getKey());
			if (d != null && e.getValue() != null)
			{
				counts.put(d, e.getValue());
			}
		}
	}

	// --- thin ConfigManager I/O ---

	public void persist(ConfigManager cm)
	{
		cm.setConfiguration(GROUP, KEY_COUNTS, toJson());
	}

	public void load(ConfigManager cm)
	{
		loadJson(cm.getConfiguration(GROUP, KEY_COUNTS));
	}
}

package com.smirnovlabs.pohteleports.cost;

import java.util.Map;
import java.util.function.IntUnaryOperator;

/**
 * The gross GP a single teleport use would otherwise have cost. Valuation is
 * decoupled from RuneLite: callers supply a price function (itemId -&gt; gp), so
 * this has no dependency on ItemManager and is trivially unit-testable with a
 * lambda. A single-method functional interface with static factory constructors.
 */
@FunctionalInterface
public interface CostBasis
{
	/** Gross GP saved for one use, given a price lookup (itemId -&gt; gp). */
	long gpPerUse(IntUnaryOperator priceFn);

	/** Sum of runes consumed by the equivalent spellbook teleport. */
	static CostBasis runes(Map<Integer, Integer> runes)
	{
		final Map<Integer, Integer> copy = Map.copyOf(runes);
		return priceFn ->
		{
			long sum = 0;
			for (Map.Entry<Integer, Integer> e : copy.entrySet())
			{
				sum += (long) priceFn.applyAsInt(e.getKey()) * e.getValue();
			}
			return sum;
		};
	}

	/** One use of a bought, charged item: its GE price divided by its charges. */
	static CostBasis itemFraction(int itemId, int charges)
	{
		return priceFn -> charges <= 0 ? 0 : (long) priceFn.applyAsInt(itemId) / charges;
	}

	/** A quantity of a consumable spent per use (e.g. lizardman fangs). */
	static CostBasis consumable(int itemId, int qtyPerUse)
	{
		return priceFn -> (long) priceFn.applyAsInt(itemId) * qtyPerUse;
	}

	/**
	 * One use of an item you <em>craft</em> rather than buy: the base item's GE
	 * price plus the runes to make it, divided across its charges. The mounted
	 * Digsite pendant is a Ruby necklace enchanted with Enchant Ruby Jewellery, so
	 * its true per-use cost is (ruby necklace + 5 fire + 1 cosmic) / 5.
	 */
	static CostBasis craftedFraction(int baseItemId, Map<Integer, Integer> makeRunes, int charges)
	{
		final Map<Integer, Integer> runes = Map.copyOf(makeRunes);
		return priceFn ->
		{
			if (charges <= 0)
			{
				return 0;
			}
			long total = priceFn.applyAsInt(baseItemId);
			for (Map.Entry<Integer, Integer> e : runes.entrySet())
			{
				total += (long) priceFn.applyAsInt(e.getKey()) * e.getValue();
			}
			return total / charges;
		};
	}

	/** No priceable equivalent — count-only, zero GP. */
	CostBasis NONE = priceFn -> 0;
}

package com.smirnovlabs.pohteleports.cost;

import com.smirnovlabs.pohteleports.model.Destination;
import java.util.function.IntUnaryOperator;

/**
 * Values a destination's saving in GP. Takes a price function (itemId -&gt; gp)
 * rather than {@code ItemManager} directly, so it is pure and unit-testable
 * with a lambda; the plugin passes {@code itemManager::getItemPrice}.
 */
public class SavingsValuator
{
	private final IntUnaryOperator priceFn;

	public SavingsValuator(IntUnaryOperator priceFn)
	{
		this.priceFn = priceFn;
	}

	public long gpPerUse(Destination d)
	{
		return d.getCostBasis().gpPerUse(priceFn);
	}

	public long gpTotal(Destination d, int count)
	{
		return gpPerUse(d) * count;
	}
}

package com.smirnovlabs.pohteleports.detect;

/**
 * Real client ids for the PoH transports. Nexus cache ids are verified against a
 * live capture; the three nexus/mounted scenery object ids have no symbolic
 * {@code gameval.ObjectID} name and were confirmed in live QA.
 */
public final class PohGameIds
{
	private PohGameIds()
	{
	}

	// ---- Nexus cache data (enum 1377 -> struct; struct params) ----
	/** enum(int destination-id -&gt; struct). {@code getEnum(1377)}. */
	public static final int NEXUS_DEST_ENUM = 1377;
	/** Struct param: destination display name (string). */
	public static final int STRUCT_PARAM_NAME = 660;
	/** Struct param: primary struct id for an "alt" teleport (e.g. Grand Exchange -&gt; Varrock). */
	public static final int STRUCT_PARAM_PRIMARY_STRUCT = 680;

	/** POH_NEXUS_LEFT_CLICK: the configured left-click default's destination-id (enum-1377 key). */
	public static final int NEXUS_DEFAULT_DEST_VARBIT = 6653;

	// Scenery object ids (MenuOptionClicked#getId on the object), confirmed in live QA.
	public static final int NEXUS_OBJECT = 33410;
	public static final int MOUNTED_GLORY_OBJECT = 13523; // ObjectID.POH_TROPHY_AMULETOFGLORY_4
	public static final int MOUNTED_XERICS_OBJECT = 33412;
	public static final int MOUNTED_DIGSITE_OBJECT = 33417;
	/** House Advertisement board — a "Visit"/"Visit-Last" on it enters another player's house. */
	public static final int HOUSE_ADVERTISEMENT_OBJECT = 29091;
}

package com.smirnovlabs.pohteleports.detect;

import com.smirnovlabs.pohteleports.model.Destination;
import java.util.Map;
import java.util.Optional;
import java.util.Set;

/** Turns a single menu interaction into a resolved teleport {@link Destination}, or nothing. */
public interface TeleportRecognizer
{
	/**
	 * Words that mark a menu option as a UI / configuration action (opening the
	 * list, editing slots, examining, ...) rather than an actual teleport. Note
	 * {@code "teleport"} is deliberately absent, so the generic left-click default
	 * ("Teleport") is kept while "Teleport menu" (→ token "menu") is rejected.
	 */
	Set<String> IGNORE_WORDS = Set.of(
		"menu", "configure", "build", "set", "select", "add",
		"remove", "empty", "examine", "rub", "recharge", "uncharge");

	/** Whole-option strings that are never a teleport (no single meaningful token). */
	Set<String> IGNORE_OPTIONS = Set.of("cancel", "continue", "ok", "close");

	Optional<Destination> onMenuInteraction(MenuInteraction e, GameStateView state);

	/**
	 * True if this (already-lowercased) option is a config/UI action we must not
	 * count as a teleport. Token-set membership, so it correctly rejects
	 * multi-word labels like "teleport menu" / "set default" without the old
	 * substring chains. An empty option (a bare object left-click) is kept.
	 */
	static boolean isIgnoredOption(String optionLower)
	{
		if (optionLower.isEmpty())
		{
			return false;
		}
		if (IGNORE_OPTIONS.contains(optionLower))
		{
			return true;
		}
		for (String word : optionLower.split("\\s+"))
		{
			if (IGNORE_WORDS.contains(word))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Match a destination name against either the option or the target text.
	 * Different transports put the destination in different fields (e.g. a
	 * mounted-amulet right-click names it in the option, a nexus list pick in
	 * the target), so we check both.
	 */
	static Destination matchName(MenuInteraction e, Map<String, Destination> nameMap)
	{
		Destination d = nameMap.get(stripKey(e.optionLower()));
		return d != null ? d : nameMap.get(stripKey(e.targetLower()));
	}

	/**
	 * Normalize a menu label for name matching: strip a leading keyboard-shortcut
	 * prefix like "[4] " / "[K] " that the Nexus UI adds, and fold the whitespace.
	 *
	 * <p>The Nexus interface separates the shortcut from the name with a
	 * <em>non-breaking</em> space (U+00A0, regex {@code \xA0}), which Java's plain
	 * {@code \s} does NOT match. Left as-is, {@code stripKey("[K] West Ardougne")}
	 * keeps the U+00A0 and returns " west ardougne", so the name lookup misses
	 * and every menu/map pick falls through to "no match". Folding {@code \xA0}
	 * together with normal whitespace fixes it. All-ASCII source on purpose — no
	 * literal non-breaking space to be mangled by an editor.
	 */
	static String stripKey(String s)
	{
		return s.replaceAll("[\\s\\xA0]+", " ")      // fold whitespace incl. non-breaking space
			.replaceFirst("^\\[[^\\]]*\\] ?", "")    // drop a leading "[4] "/"[K] " nexus shortcut
			.replaceFirst("^\\d+:\\s*", "")          // drop a leading "1: " MENU_NEW option number
			.trim();
	}
}

package com.smirnovlabs.pohteleports.detect;

import com.smirnovlabs.pohteleports.model.Destination;
import com.smirnovlabs.pohteleports.model.Transport;
import java.util.Map;
import java.util.Optional;

/**
 * Nexus teleports, resolved in three fail-safe layers:
 *
 * <ol>
 *   <li><b>Name map</b> — the clicked option/target matched against our known
 *       destination names. Authoritative for every recognized label.</li>
 *   <li><b>Cache catalog</b> — only when {@link NexusCatalog#isLoaded()}. Rescues
 *       an unrecognised name (matched against the game's own cache names, so it is
 *       rename-proof) and resolves the generic left-click <em>default</em> from the
 *       configured-default varbit ({@code 6653}). Struct ids bridge back to a
 *       {@link Destination} via {@link NexusStructIndex}.</li>
 *   <li><b>Unknown</b> — a generic default on the nexus object that nothing above
 *       resolved falls to the count-only Unknown bucket.</li>
 * </ol>
 *
 * <p>The catalog is optional (null = disabled) and only ever <em>adds</em>
 * resolution: if the cache ids are wrong it never loads and this behaves
 * identically to the name-map-only version.
 */
public class NexusRecognizer implements TeleportRecognizer
{
	private final int nexusObjectId;
	private final Map<String, Destination> nameMap;     // lowercased name -> Destination
	private final NexusCatalog catalog;                 // nullable: cache-backed rescue + left-click default

	public NexusRecognizer(int nexusObjectId, Map<String, Destination> nameMap)
	{
		this(nexusObjectId, nameMap, null);
	}

	public NexusRecognizer(int nexusObjectId, Map<String, Destination> nameMap, NexusCatalog catalog)
	{
		this.nexusObjectId = nexusObjectId;
		this.nameMap = nameMap;
		this.catalog = catalog;
	}

	@Override
	public Optional<Destination> onMenuInteraction(MenuInteraction e, GameStateView state)
	{
		String option = e.optionLower();
		if (TeleportRecognizer.isIgnoredOption(option))
		{
			return Optional.empty(); // opening the list / config / build — never a teleport
		}

		// 1) Known name — authoritative.
		Destination byName = TeleportRecognizer.matchName(e, nameMap);
		if (byName != null)
		{
			return Optional.of(byName);
		}

		// 2) Cache-backed rescue + left-click default — only when the catalog loaded.
		if (catalog != null && catalog.isLoaded())
		{
			Destination byCatalog = resolveViaCatalog(e, option, state);
			if (byCatalog != null)
			{
				return Optional.of(byCatalog);
			}
		}

		// 3) A generic default on the nexus object that stayed unresolved -> Unknown bucket.
		if (e.getId() == nexusObjectId && (option.contains("teleport") || option.isEmpty()))
		{
			return Optional.of(Destination.unknownFor(Transport.NEXUS));
		}
		return Optional.empty();
	}

	/** Resolve a nexus struct id from the cache (by name, then the left-click default varbit) and bridge to a Destination. */
	private Destination resolveViaCatalog(MenuInteraction e, String option, GameStateView state)
	{
		Integer struct = catalog.structForName(TeleportRecognizer.stripKey(e.targetLower()));
		if (struct == null)
		{
			struct = catalog.structForName(TeleportRecognizer.stripKey(option));
		}
		if (struct == null && e.getId() == nexusObjectId && (option.contains("teleport") || option.isEmpty()))
		{
			struct = catalog.structForDestValue(state.getVarbit(PohGameIds.NEXUS_DEFAULT_DEST_VARBIT));
		}
		return struct == null ? null : NexusStructIndex.forStruct(struct);
	}
}

