package com.smirnovlabs.pohteleports.detect;

/**
 * Tracks whether the player is currently in <em>their own</em> POH or a guest's,
 * for the "count guest POHs" config toggle. Map regions can't tell them apart
 * (POH regions follow the house's chosen location, not its owner), so we use the
 * entry method instead: you reach a guest's house by clicking "Visit" on a House
 * Advertisement board; you reach your own by any other means (portal, spell,
 * tablet). A pending board-visit is "consumed" by the next instance entry, and
 * everything resets on leaving the instance.
 *
 * <p>Pure and client-free (driven by two booleans) so it is unit-testable.
 */
public final class HouseOwnershipTracker
{
	/** Ticks a pending board-visit stays valid (covers browsing the board) before we assume it was cancelled. */
	private static final int PENDING_TTL = 100;

	private boolean inGuestHouse;
	private int pendingVisitTicks; // > 0 while a board-visit awaits the house entry
	private boolean wasInstanced;

	/** Player clicked "Visit" on a House Advertisement board — the next house entered is a guest's. */
	public void onBoardVisit()
	{
		pendingVisitTicks = PENDING_TTL;
	}

	/** Call every game tick with whether the player is currently in an instanced region. */
	public void onTick(boolean instanced)
	{
		if (instanced && !wasInstanced)
		{
			inGuestHouse = pendingVisitTicks > 0; // entered a POH: guest iff a board-visit was pending
			pendingVisitTicks = 0;
		}
		else if (!instanced)
		{
			inGuestHouse = false; // outside any POH
			if (pendingVisitTicks > 0)
			{
				pendingVisitTicks--; // expire a visit that never led into a house (cancelled)
			}
		}
		wasInstanced = instanced;
	}

	/** True while the player is in another player's house (not their own). */
	public boolean inGuestHouse()
	{
		return inGuestHouse;
	}
}

package com.smirnovlabs.pohteleports.detect;

import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.StructComposition;

/**
 * Production {@link CacheView}: adapts the RuneLite {@link Client}'s cache
 * accessors. Every read is wrapped so an unloaded, missing, or wrong-typed
 * param reads as "absent" ({@code empty} / {@code 0} / {@code null}) instead of
 * throwing — {@code StructComposition.getIntValue} throws
 * {@code IllegalArgumentException} when the param is actually a string param, and
 * the catalog must never let that (or any cache surprise) escape into the click
 * handler. Must be used on the client thread.
 */
public final class ClientCacheView implements CacheView
{
	private final Client client;

	public ClientCacheView(Client client)
	{
		this.client = client;
	}

	@Override
	public int[] enumKeys(int enumId)
	{
		try
		{
			EnumComposition e = client.getEnum(enumId);
			return e == null ? new int[0] : e.getKeys();
		}
		catch (RuntimeException ex)
		{
			return new int[0];
		}
	}

	@Override
	public int enumValue(int enumId, int key)
	{
		try
		{
			EnumComposition e = client.getEnum(enumId);
			return e == null ? 0 : e.getIntValue(key);
		}
		catch (RuntimeException ex)
		{
			return 0;
		}
	}

	@Override
	public int structInt(int structId, int paramId)
	{
		try
		{
			StructComposition s = client.getStructComposition(structId);
			return s == null ? 0 : s.getIntValue(paramId);
		}
		catch (RuntimeException ex)
		{
			return 0; // e.g. paramId is a string param on this struct
		}
	}

	@Override
	public String structString(int structId, int paramId)
	{
		try
		{
			StructComposition s = client.getStructComposition(structId);
			return s == null ? null : s.getStringValue(paramId);
		}
		catch (RuntimeException ex)
		{
			return null; // e.g. paramId is an int param on this struct
		}
	}
}

package com.smirnovlabs.pohteleports.detect;

/**
 * Narrow, read-only window onto the game cache — the two enum accessors and two
 * struct-param accessors {@link NexusCatalog} needs, and nothing else. Mirrors
 * the {@link GameStateView} pattern: production adapts the RuneLite {@code Client}
 * to this interface, tests supply a plain map-backed fake, so the catalog's
 * folding logic is unit-testable without mocking the whole client.
 *
 * <p>All methods must be called on the client thread in production. Accessors
 * return an "absent" value ({@code empty array} / {@code 0} / {@code null})
 * rather than throwing when the cache is not yet loaded, so a caller can probe
 * readiness by checking {@link #enumKeys}.
 */
public interface CacheView
{
	/** Keys of an {@code int->int} enum; an empty array if the enum is not loaded yet. */
	int[] enumKeys(int enumId);

	/** Value of an {@code int->int} enum at {@code key} (0 if absent). */
	int enumValue(int enumId, int key);

	/** Int-valued struct parameter (0 if the struct or the param is absent). */
	int structInt(int structId, int paramId);

	/** String-valued struct parameter (null if the struct or the param is absent). */
	String structString(int structId, int paramId);
}

