	}
}

package com.smirnovlabs.pohteleports.detect;

import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

/**
 * Reads the Portal Nexus destination table from the game cache at runtime, so
 * destination names never have to be hardcoded or guessed.
 *
 * <p>enum {@code 1377} maps an int destination-id to a teleport struct; struct
 * param {@code 660} is the destination name. The alt&rarr;primary link (param
 * {@code 680}) and the scry variant (destination-id {@code + 150}) are folded in
 * at build time, so every lookup is a plain O(1) map get with no further cache call.
 *
 * <p>Built lazily <em>exactly once</em> per session via {@link #ensureLoaded} —
 * nothing is read at plugin start-up, and if the cache is not ready (or the ids
 * are wrong) it stays unloaded and retries next time. All calls must be on the
 * client thread. Reads go through the narrow {@link CacheView} so the folding
 * logic is unit-testable without a live client.
 */
public final class NexusCatalog
{
	private static final int SCRY_OFFSET = 150;

	private boolean loaded;
	private final Map<Integer, Integer> destToStruct = new HashMap<>(); // enum key (+scry) -> primary struct id
	private final Map<Integer, String> structToName = new HashMap<>();  // primary struct id -> game name
	private final Map<String, Integer> nameToStruct = new HashMap<>();  // lowercased game name -> primary struct id

	/**
	 * Build the maps on first call; later calls are a cheap boolean check. Safe to
	 * call before the cache is ready — it stays unloaded and retries next time.
	 */
	public void ensureLoaded(CacheView cache)
	{
		if (loaded)
		{
			return;
		}
		int[] keys = cache.enumKeys(PohGameIds.NEXUS_DEST_ENUM);
		if (keys.length == 0)
		{
			return; // cache not ready (or the enum id is wrong) — retry later, stay unloaded
		}
		for (int destId : keys)
		{
			try
			{
				loadDestination(cache, destId);
			}
			catch (RuntimeException ex)
			{
				// A misbehaving cache read (wrong-typed or absent param) must never abort
				// the whole catalog — skip just this destination and keep the rest.
			}
		}
		loaded = !structToName.isEmpty();
	}

	private void loadDestination(CacheView cache, int destId)
	{
		int ownStruct = cache.enumValue(PohGameIds.NEXUS_DEST_ENUM, destId);
		if (ownStruct <= 0)
		{
			return;
		}
		int primary = cache.structInt(ownStruct, PohGameIds.STRUCT_PARAM_PRIMARY_STRUCT);
		int structId = primary > 0 ? primary : ownStruct;

		destToStruct.put(destId, structId);
		destToStruct.put(destId + SCRY_OFFSET, structId); // scry variant resolves to the same destination

		if (!structToName.containsKey(structId))
		{
			String name = cache.structString(structId, PohGameIds.STRUCT_PARAM_NAME);
			if (name != null && !name.isEmpty())
			{
				structToName.put(structId, name);
				nameToStruct.put(name.toLowerCase(Locale.ROOT), structId);
			}
		}
	}

	public boolean isLoaded()
	{
		return loaded;
	}

	/** Number of distinct destination names read from the cache (0 until loaded). */
	public int size()
	{
		return structToName.size();
	}

	/** Primary struct id for a raw slot / left-click varbit value, or null. O(1), no cache call. */
	public Integer structForDestValue(int destValue)
	{
		return destToStruct.get(destValue);
	}

	/** Primary struct id for a cache display name (case-insensitive), or null. O(1). */
	public Integer structForName(String name)
	{
		return name == null ? null : nameToStruct.get(name.toLowerCase(Locale.ROOT));
	}

	/** Cache-sourced display name for a struct id, or null if unknown. */
	public String name(int structId)
	{
		return structToName.get(structId);
	}
}

package com.smirnovlabs.pohteleports.detect;

/** The slice of live game state detection needs, so it can be faked in tests. */
public interface GameStateView
{
	int getVarbit(int varbitId);

	/** True while the player is in any POH (own or a guest's), by region allowlist. */
	boolean isInPoh();

	int currentTick();

	/**
	 * The player's world position as {@code {x, y, plane}}, or null if unavailable.
	 * Used to confirm a teleport by the large single-tick coordinate jump it causes.
	 */
	int[] playerPos();
}

package com.smirnovlabs.pohteleports.detect;

import com.smirnovlabs.pohteleports.model.Destination;
import com.smirnovlabs.pohteleports.model.Transport;
import java.util.Map;
import java.util.Optional;

/**
 * Mounted amulets that expose destinations as right-click options directly on
 * the object: mounted glory, mounted Xeric's talisman, mounted Digsite pendant.
 * Scoped by object id. A named option resolves by name; a generic "Teleport"
 * (with no named destination) falls to the count-only Unknown bucket; other
 * options (Examine, Rub, Configure, "Teleport menu", ...) are ignored. One
 * instance per transport.
 */
public class MountedAmuletRecognizer implements TeleportRecognizer
{
	private final int objectId;
	private final Transport transport;
	private final Map<String, Destination> nameMap;

	public MountedAmuletRecognizer(int objectId, Transport transport, Map<String, Destination> nameMap)
	{
		this.objectId = objectId;
		this.transport = transport;
		this.nameMap = nameMap;
	}

	@Override
	public Optional<Destination> onMenuInteraction(MenuInteraction e, GameStateView state)
	{
		if (e.getId() != objectId)
		{
			return Optional.empty();
		}
		Destination byName = TeleportRecognizer.matchName(e, nameMap);
		if (byName != null)
		{
			return Optional.of(byName);
		}
		// A bare "Teleport" on the object (no named destination — mounted amulets have no
		// configurable left-click default) counts, as the transport's Unknown bucket.
		String option = e.optionLower();
		if (!TeleportRecognizer.isIgnoredOption(option) && option.contains("teleport"))
		{
			return Optional.of(Destination.unknownFor(transport));
		}
		return Optional.empty();
	}
}

package com.smirnovlabs.pohteleports.detect;

import com.smirnovlabs.pohteleports.model.Destination;
import com.smirnovlabs.pohteleports.model.TeleportEvent;
import java.util.List;
import java.util.Optional;
import java.util.function.Consumer;

/**
 * Recognizes a teleport destination from a menu interaction, then counts it only
 * once the player <em>actually</em> teleports — confirmed by the large single-tick
 * world-coordinate jump a teleport causes.
 *
 * <p>This is accurate by construction: a cancelled Wilderness warning, a denied
 * teleport, or just opening the menu never produces a jump, so it never counts.
 * It also replaces the brittle same-tick / denial-message guards the old
 * count-on-click model needed. Walking or running never trips it — those move a
 * couple of tiles per tick, far below {@link #JUMP_TILES}; a teleport moves
 * hundreds in one tick.
 *
 * <p>Flow: {@link #onMenuInteraction} arms a pending destination; {@link #onGameTick}
 * (called every tick) confirms it on a jump, or discards it after
 * {@link #ARM_WINDOW_TICKS} without one (covers the delay of a Wilderness warning).
 */
public class DetectionRouter
{
	/** Minimum single-tick move (tiles) that counts as a teleport, not walking. Compared squared. */
	private static final int JUMP_TILES = 15;
	/** Ticks a recognized teleport stays armed awaiting the jump (covers the Wilderness warning click). */
	private static final int ARM_WINDOW_TICKS = 10;

	private final List<TeleportRecognizer> recognizers;
	private final GameStateView state;
	private final Consumer<TeleportEvent> sink;
	private final Consumer<String> trace; // nullable diagnostics

	private Destination pending;
	private int pendingArmTick;
	private int[] lastPos;

	public DetectionRouter(List<TeleportRecognizer> recognizers, GameStateView state, Consumer<TeleportEvent> sink)
	{
		this(recognizers, state, sink, null);
	}

	public DetectionRouter(List<TeleportRecognizer> recognizers, GameStateView state,
		Consumer<TeleportEvent> sink, Consumer<String> trace)
	{
		this.recognizers = recognizers;
		this.state = state;
		this.sink = sink;
		this.trace = trace;
	}

	/** A recognized teleport arms a pending count; the count itself waits for the coord jump. */
	public void onMenuInteraction(MenuInteraction e)
	{
		if (!state.isInPoh())
		{
			trace("skip (not in POH): " + desc(e));
			return;
		}
		for (TeleportRecognizer r : recognizers)
		{
			Optional<Destination> d = r.onMenuInteraction(e, state);
			if (d.isPresent())
			{
				pending = d.get();
				pendingArmTick = state.currentTick();
				lastPos = state.playerPos(); // anchor for the jump check; ticks are idle until now
				trace("armed " + pending + " (awaiting teleport): " + desc(e));
				return;
			}
		}
		trace("no match: " + desc(e) + " [norm option='" + TeleportRecognizer.stripKey(e.optionLower())
			+ "' target='" + TeleportRecognizer.stripKey(e.targetLower()) + "']");
	}

	/**
	 * Every game tick: confirm a pending teleport on a big coord jump, else expire it.
	 * Does <em>nothing</em> (not even a position read) when no teleport is armed, which is
	 * almost always — position is only tracked during the brief arm-to-confirm window.
	 */
	public void onGameTick()
	{
		if (pending == null)
		{
			return;
		}
		int[] pos = state.playerPos();
		if (jumped(lastPos, pos))
		{
			trace("counted " + pending + " (teleport confirmed by coord jump)");
			sink.accept(new TeleportEvent(pending, state.currentTick()));
			pending = null;
		}
		else if (state.currentTick() - pendingArmTick >= ARM_WINDOW_TICKS)
		{
			trace("discarded " + pending + " (no teleport within window)");
			pending = null;
		}
		lastPos = pos;
	}

	/** A large single-tick move in the horizontal plane — a teleport, not walking. */
	private static boolean jumped(int[] from, int[] to)
	{
		if (from == null || to == null)
		{
			return false;
		}
		long dx = from[0] - to[0];
		long dy = from[1] - to[1];
		return dx * dx + dy * dy > (long) JUMP_TILES * JUMP_TILES;
	}

	private void trace(String msg)
	{
		if (trace != null)
		{
			trace.accept(msg);
		}
	}

	private static String desc(MenuInteraction e)
	{
		return "option='" + e.getOption() + "' target='" + e.getTarget() + "' id=" + e.getId();
	}
}

